const BODY_CONTENT = "\n\n  <!-- ==================== 1. HEADER ==================== -->\n  <header class=\"site-header\">\n    <div class=\"header-inner container\">\n      <!-- LOGO -->\n      <a href=\"/contextos#hero\" class=\"brand-logo\">\n        <span class=\"logo-mark\">C</span>\n        <span class=\"brand-name\">Context<strong>OS</strong></span>\n      </a>\n\n      <!-- NAV LINKS -->\n      <nav class=\"nav-menu\">\n        <a href=\"/contextos#hero\" class=\"nav-link active\">Home</a>\n        <a href=\"#features\" class=\"nav-link\">Features</a>\n        <a href=\"#about\" class=\"nav-link\">About</a>\n        <a href=\"#social-proof\" class=\"nav-link\">Customers</a>\n        <a href=\"#pricing\" class=\"nav-link\">Pricing</a>\n        <a href=\"#faq\" class=\"nav-link\">FAQ</a>\n        <a href=\"/contextos/audit\" target=\"_blank\" class=\"nav-link\" style=\"color: var(--color-brand-blue); font-weight: 600;\">Sample Audit</a>\n      </nav>\n\n      <!-- CTA -->\n      <div class=\"header-actions\">\n        <button class=\"btn btn-secondary-subtle\" id=\"navSignInBtn\">Sign In</button>\n        <button class=\"btn btn-primary\" id=\"navSignUpBtn\">Sign Up</button>\n      </div>\n    </div>\n  </header>\n\n  <!-- ==================== 2. HERO SECTION ==================== -->\n  <section class=\"hero-section\" id=\"hero\">\n    <div class=\"hero-inner container\">\n      <!-- Left Column: Copy & Actions -->\n      <div class=\"hero-content\">\n        <div class=\"hero-pill\">\n          <span class=\"pill-dot\"></span>\n          <span>Zero-Manual Institutional Memory</span>\n        </div>\n\n        <h1 class=\"hero-headline\">\n          Stop your team from re-solving problems you already solved.\n        </h1>\n\n        <p class=\"hero-subtext\">\n          ContextOS passively captures the \"why\" behind critical decisions from Slack, PRs, and meetings. When your team scales past 30 people, eliminate the invisible coordination drag that turns startup velocity into corporate slow motion.\n        </p>\n\n        <div class=\"hero-cta-group\">\n          <button class=\"btn btn-primary btn-lg\" id=\"heroGetStartedBtn\">Get Started Free</button>\n          <a href=\"/contextos/audit\" target=\"_blank\" class=\"btn btn-outline btn-lg\">View Sample Audit (PDF)</a>\n        </div>\n\n        <div class=\"hero-proof-bar\">\n          <div class=\"proof-item\">\n            <span class=\"proof-check\">\u2713</span>\n            <span>Zero manual documentation</span>\n          </div>\n          <div class=\"proof-item\">\n            <span class=\"proof-check\">\u2713</span>\n            <span>48-hour Slack integration</span>\n          </div>\n          <div class=\"proof-item\">\n            <span class=\"proof-check\">\u2713</span>\n            <span>SOC2 Type II compliant</span>\n          </div>\n        </div>\n      </div>\n\n      <!-- Right Column: Interactive Illustration / Product Preview -->\n      <div class=\"hero-media\" id=\"interactive-preview\">\n        <div class=\"mockup-window\">\n          <div class=\"mockup-chrome\">\n            <div class=\"chrome-dots\">\n              <span class=\"dot red\"></span>\n              <span class=\"dot yellow\"></span>\n              <span class=\"dot green\"></span>\n            </div>\n            <div class=\"chrome-url\">contextos.internal / live-decision-radar</div>\n            <div class=\"chrome-badge\">Active Radar</div>\n          </div>\n\n          <div class=\"mockup-body\">\n            <!-- Simulated Search / Radar -->\n            <div class=\"mockup-search\">\n              <svg width=\"15\" height=\"15\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><path d=\"m21 21-4.3-4.3\"/></svg>\n              <input type=\"text\" id=\"demoQueryInput\" value=\"Should we switch checkout provider to Adyen?\" readonly>\n              <span class=\"mockup-tag\">Preemptive Intercept</span>\n            </div>\n\n            <!-- Intercept Card -->\n            <div class=\"mockup-card alert-card\">\n              <div class=\"card-status-row\">\n                <span class=\"flag-pill\">Historical Precedent Found</span>\n                <span class=\"flag-date\">Feb 14, 2025 \u2022 8 mos ago</span>\n              </div>\n              <h4 class=\"card-headline\">Adyen Evaluated & Rejected for European Rollout</h4>\n              <p class=\"card-desc\">\n                Sarah Jenkins (Billing Lead) tested Adyen against Stripe Connect. Minimum \u20ac120/mo platform charge & KYC verification latency in Germany led to an 18% onboarding abandonment rate.\n              </p>\n              <div class=\"card-meta-row\">\n                <div class=\"meta-tag\"><strong>Decision:</strong> Retain Stripe Connect</div>\n                <div class=\"meta-tag danger\"><strong>Rejected:</strong> Adyen</div>\n              </div>\n              <div class=\"card-outcome-banner\">\n                <strong>ContextOS Intercept:</strong> Prevented 3 weeks of duplicated vendor evaluations.\n              </div>\n            </div>\n\n            <!-- Mini Live Stream -->\n            <div class=\"mockup-stream-preview\">\n              <span class=\"stream-label\">Ambient Stream Ingest:</span>\n              <div class=\"stream-pill\">#eng-core: Redis Token Bucket locked \u2713</div>\n              <div class=\"stream-pill\">PR #348: SSE over WebSockets locked \u2713</div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- ==================== 3. FEATURES (CARD 1, 2, 3) ==================== -->\n  <section class=\"features-section\" id=\"features\">\n    <div class=\"container\">\n      <div class=\"section-header\">\n        <span class=\"section-tag\">Core Capabilities</span>\n        <h2 class=\"section-title\">Built for companies that value velocity over bureaucracy</h2>\n        <p class=\"section-subtitle\">\n          Standard tools force employees to maintain wikis that decay in 3 weeks. ContextOS operates silently in the background of your actual workflow.\n        </p>\n      </div>\n\n      <div class=\"features-grid\">\n        <!-- CARD 1 -->\n        <div class=\"feature-card\">\n          <div class=\"card-icon-wrap\">\n            <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M4 14.899A7 7 0 1 1 15.71 8h1.79a4.5 4.5 0 0 1 2.5 8.242\"/><path d=\"M12 12v9\"/><path d=\"m8 17 4 4 4-4\"/></svg>\n          </div>\n          <span class=\"card-number\">01</span>\n          <h3 class=\"card-title\">Ambient Context Ingestion</h3>\n          <p class=\"card-body\">\n            Connects to Slack channels, GitHub PR discussions, and Zoom meeting transcripts. Automatically synthesizes why decisions were made without requiring a single employee to write documentation.\n          </p>\n          <ul class=\"card-list\">\n            <li>Zero forms or manual wiki entry</li>\n            <li>Separates casual chatter from locked decisions</li>\n            <li>Retains key trade-offs and rejected alternatives</li>\n          </ul>\n        </div>\n\n        <!-- CARD 2 -->\n        <div class=\"feature-card highlight-card\">\n          <div class=\"card-icon-wrap\">\n            <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"m16 12-4-4-4 4M12 16V8\"/></svg>\n          </div>\n          <span class=\"card-number\">02</span>\n          <h3 class=\"card-title\">Preemptive Memory Radar</h3>\n          <p class=\"card-body\">\n            Detects when an engineer or product manager is about to start an initiative that was already attempted or rejected in the past. Surfaces original constraints and saves weeks of repeated work.\n          </p>\n          <ul class=\"card-list\">\n            <li>Preempts redundant vendor evaluations</li>\n            <li>Alerts on conflicting architectural directions</li>\n            <li>Preserves context across team departures</li>\n          </ul>\n        </div>\n\n        <!-- CARD 3 -->\n        <div class=\"feature-card\">\n          <div class=\"card-icon-wrap\">\n            <svg width=\"22\" height=\"22\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M22 12h-4l-3 9L9 3l-3 9H2\"/></svg>\n          </div>\n          <span class=\"card-number\">03</span>\n          <h3 class=\"card-title\">The Meeting Killer Digest</h3>\n          <p class=\"card-body\">\n            Eliminates time-wasting daily standups and weekly cross-functional status syncs. Synthesizes a daily 60-second executive pulse of what changed, what was locked, and what is currently blocked.\n          </p>\n          <ul class=\"card-list\">\n            <li>Reduces recurring calendar syncs by up to 60%</li>\n            <li>Clear decision ownership & accountability</li>\n            <li>Instant onboarding ramp for new hires</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- ==================== 4. TESTIMONIALS & SOCIAL PROOF ==================== -->\n  <section class=\"social-proof-section\" id=\"social-proof\">\n    <div class=\"container\">\n      <!-- Metrics Bar -->\n      <div class=\"metrics-row\">\n        <div class=\"metric-block\">\n          <span class=\"metric-value\">42.8 hrs</span>\n          <span class=\"metric-desc\">Average weekly synchronization time saved per team</span>\n        </div>\n        <div class=\"metric-divider\"></div>\n        <div class=\"metric-block\">\n          <span class=\"metric-value\">100%</span>\n          <span class=\"metric-desc\">Passive extraction with zero manual documentation</span>\n        </div>\n        <div class=\"metric-divider\"></div>\n        <div class=\"metric-block\">\n          <span class=\"metric-value\">85%</span>\n          <span class=\"metric-desc\">Reduction in redundant architectural debate</span>\n        </div>\n      </div>\n\n      <!-- Testimonial Cards -->\n      <div class=\"testimonials-grid\">\n        <div class=\"testimonial-card\">\n          <p class=\"testimonial-quote\">\n            \"When we grew from 15 to 45 engineers, our velocity fell off a cliff. We were constantly debating choices we'd already settled 6 months prior. ContextOS paid for itself in week one.\"\n          </p>\n          <div class=\"testimonial-author\">\n            <div class=\"author-avatar\">MR</div>\n            <div class=\"author-info\">\n              <span class=\"author-name\">Marcus Ray</span>\n              <span class=\"author-role\">VP of Engineering, Series B Fintech</span>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"testimonial-card\">\n          <p class=\"testimonial-quote\">\n            \"Our senior backend lead resigned, and normally that would mean months of blindness. ContextOS retained every vendor evaluation, architectural reason, and edge case nuance intact.\"\n          </p>\n          <div class=\"testimonial-author\">\n            <div class=\"author-avatar\">EL</div>\n            <div class=\"author-info\">\n              <span class=\"author-name\">Elena Lindqvist</span>\n              <span class=\"author-role\">Co-Founder & CTO, Cloud Infrastructure</span>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"testimonial-card\">\n          <p class=\"testimonial-quote\">\n            \"We killed our 30-minute daily cross-team standup completely. The daily synthesized pulse gives everyone exactly what they need without calendar interruption.\"\n          </p>\n          <div class=\"testimonial-author\">\n            <div class=\"author-avatar\">TS</div>\n            <div class=\"author-info\">\n              <span class=\"author-name\">Tariq Sayed</span>\n              <span class=\"author-role\">Chief of Staff, Remote SaaS Platform</span>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- ==================== 5. PRICING & FAQ ==================== -->\n  <section class=\"pricing-faq-section\" id=\"pricing\">\n    <div class=\"container\">\n      <div class=\"section-header\">\n        <span class=\"section-tag\">Predictable Plans</span>\n        <h2 class=\"section-title\">Simple, transparent pricing for growing teams</h2>\n        <p class=\"section-subtitle\">\n          Recover hundreds of hours of high-value engineering time. Every plan starts with a 14-day free trial.\n        </p>\n\n        <!-- Billing Toggle -->\n        <div class=\"billing-toggle\">\n          <span class=\"toggle-label\" id=\"monthlyLabel\">Monthly</span>\n          <button class=\"toggle-switch\" id=\"billingToggleBtn\" aria-label=\"Toggle annual billing\"></button>\n          <span class=\"toggle-label active\" id=\"annualLabel\">Annual <span class=\"discount-badge\">Save 20%</span></span>\n        </div>\n      </div>\n\n      <!-- Pricing Cards -->\n      <div class=\"pricing-grid\">\n        <!-- Plan 1 -->\n        <div class=\"pricing-card\">\n          <div class=\"plan-header\">\n            <h3 class=\"plan-name\">Seed Stage</h3>\n            <p class=\"plan-desc\">For fast-moving early teams beginning to scale coordination.</p>\n          </div>\n          <div class=\"plan-price\">\n            <span class=\"currency\">$</span>\n            <span class=\"price-val\" data-monthly=\"499\" data-annual=\"399\">399</span>\n            <span class=\"period\">/ month</span>\n          </div>\n          <ul class=\"plan-features\">\n            <li>Up to 25 team members</li>\n            <li>Slack & Google Workspace connector</li>\n            <li>Decision Lineage graph</li>\n            <li>7-day historical context indexing</li>\n            <li>Email support</li>\n          </ul>\n          <button class=\"btn btn-secondary-subtle btn-block btn-plan\" data-plan=\"Seed Stage\">Get Started</button>\n        </div>\n\n        <!-- Plan 2: Featured -->\n        <div class=\"pricing-card featured\">\n          <div class=\"popular-ribbon\">Most Popular</div>\n          <div class=\"plan-header\">\n            <h3 class=\"plan-name\">Growth</h3>\n            <p class=\"plan-desc\">For scaling companies experiencing communication overhead.</p>\n          </div>\n          <div class=\"plan-price\">\n            <span class=\"currency\">$</span>\n            <span class=\"price-val\" data-monthly=\"1199\" data-annual=\"899\">899</span>\n            <span class=\"period\">/ month</span>\n          </div>\n          <ul class=\"plan-features\">\n            <li>Up to 100 team members</li>\n            <li>Slack, Zoom, GitHub & Jira ingestion</li>\n            <li>Preemptive Memory Radar</li>\n            <li>The Meeting Killer daily pulse</li>\n            <li>Unlimited historical context retention</li>\n            <li>Dedicated onboarding engineer</li>\n          </ul>\n          <button class=\"btn btn-primary btn-block btn-plan\" data-plan=\"Growth\">Start 14-Day Free Trial</button>\n        </div>\n\n        <!-- Plan 3 -->\n        <div class=\"pricing-card\">\n          <div class=\"plan-header\">\n            <h3 class=\"plan-name\">Scale & Enterprise</h3>\n            <p class=\"plan-desc\">For established organizations with custom security requirements.</p>\n          </div>\n          <div class=\"plan-price\">\n            <span class=\"price-val custom\">Custom</span>\n            <span class=\"period\">tailored deployment</span>\n          </div>\n          <ul class=\"plan-features\">\n            <li>Unlimited team members</li>\n            <li>Private on-prem or VPC LLM deployment</li>\n            <li>Custom ERP & CRM integrations</li>\n            <li>SOC2 Type II audit logs & SSO/SAML</li>\n            <li>Guaranteed 99.9% uptime SLA</li>\n            <li>Dedicated customer success partner</li>\n          </ul>\n          <button class=\"btn btn-secondary-subtle btn-block btn-plan\" data-plan=\"Enterprise\">Contact Sales</button>\n        </div>\n      </div>\n\n      <!-- FAQ Accordion -->\n      <div class=\"faq-container\" id=\"faq\">\n        <h3 class=\"faq-title\">Frequently Asked Questions</h3>\n        \n        <div class=\"faq-accordion\">\n          <div class=\"faq-item\">\n            <button class=\"faq-question\">\n              <span>How does ContextOS capture decisions without asking employees to write docs?</span>\n              <span class=\"faq-icon\">+</span>\n            </button>\n            <div class=\"faq-answer\">\n              <p>ContextOS connects via read-only APIs to the communication tools you already use\u2014such as Slack threads, GitHub pull request comments, and meeting transcripts. It utilizes state-of-the-art causal extraction models that distinguish casual conversations from finalized consensus, extracting the rationale, rejected alternatives, and ownership without requiring any manual data entry.</p>\n            </div>\n          </div>\n\n          <div class=\"faq-item\">\n            <button class=\"faq-question\">\n              <span>How is this different from tools like Glean or Notion?</span>\n              <span class=\"faq-icon\">+</span>\n            </button>\n            <div class=\"faq-answer\">\n              <p>Glean is an enterprise search engine that only indexes documents already written, while Notion requires employees to continually draft and update static wikis (which decay within 30 days). ContextOS is an autonomous intelligence layer that actively synthesizes living context and preemptively alerts you <em>before</em> you repeat mistakes, rather than waiting for you to search for keywords.</p>\n            </div>\n          </div>\n\n          <div class=\"faq-item\">\n            <button class=\"faq-question\">\n              <span>Is our company conversation data kept private and secure?</span>\n              <span class=\"faq-icon\">+</span>\n            </button>\n            <div class=\"faq-answer\">\n              <p>Yes. Your organizational data is strictly isolated in dedicated, encrypted databases (AES-256 at rest, TLS 1.3 in transit). We do not train public models on your proprietary data, and we support zero-data-retention (ZDR) policies as well as private VPC deployments for enterprise customers.</p>\n            </div>\n          </div>\n\n          <div class=\"faq-item\">\n            <button class=\"faq-question\">\n              <span>What is the 48-Hour Institutional Memory Audit?</span>\n              <span class=\"faq-icon\">+</span>\n            </button>\n            <div class=\"faq-answer\">\n              <p>The audit is a non-invasive, free assessment where we connect read-only to your workspace for 48 hours. We generate an executive report showing exactly how much time and payroll your team is currently losing to coordination drag and duplicate problem-solving, along with a live demo of your company's own context graph.</p>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- ==================== 6. FOOTER ==================== -->\n  <footer class=\"site-footer\">\n    <div class=\"container footer-grid\">\n      <!-- Col 1: Links -->\n      <div class=\"footer-col\">\n        <h4 class=\"footer-col-title\">Product</h4>\n        <ul class=\"footer-links\">\n          <li><a href=\"#features\">Ambient Ingestion</a></li>\n          <li><a href=\"/contextos#hero\">Preemptive Radar</a></li>\n          <li><a href=\"#features\">Meeting Killer</a></li>\n          <li><a href=\"#pricing\">Pricing Plans</a></li>\n          <li><a href=\"#faq\">Security & SOC2</a></li>\n        </ul>\n      </div>\n\n      <!-- Col 2: Links -->\n      <div class=\"footer-col\">\n        <h4 class=\"footer-col-title\">Company</h4>\n        <ul class=\"footer-links\">\n          <li><a href=\"#about\">About Us</a></li>\n          <li><a href=\"#about\">Manifesto</a></li>\n          <li><a href=\"#social-proof\">Customer Stories</a></li>\n          <li><a href=\"#about\">Careers</a></li>\n          <li><a href=\"#about\">Press Inquiries</a></li>\n        </ul>\n      </div>\n\n      <!-- Col 3: Social -->\n      <div class=\"footer-col\">\n        <h4 class=\"footer-col-title\">Connect & Community</h4>\n        <ul class=\"footer-links\">\n          <li><a href=\"https://x.com\" target=\"_blank\" rel=\"noopener\">X / Twitter</a></li>\n          <li><a href=\"https://linkedin.com\" target=\"_blank\" rel=\"noopener\">LinkedIn</a></li>\n          <li><a href=\"https://github.com\" target=\"_blank\" rel=\"noopener\">GitHub</a></li>\n          <li><a href=\"mailto:contact@contextos.internal\">Support Email</a></li>\n          <li><a href=\"#about\">Office & Status</a></li>\n        </ul>\n      </div>\n\n      <!-- Col 4: Newsletter -->\n      <div class=\"footer-col newsletter-col\">\n        <h4 class=\"footer-col-title\">Stay Updated</h4>\n        <p class=\"newsletter-desc\">\n          Subscribe to our weekly dispatch on organizational entropy, engineering velocity, and the mathematics of scaling teams.\n        </p>\n        <form class=\"newsletter-form\" id=\"newsletterForm\">\n          <input type=\"email\" class=\"newsletter-input\" id=\"newsletterEmail\" placeholder=\"Enter your work email\" required>\n          <button type=\"submit\" class=\"btn btn-primary btn-newsletter\">Subscribe</button>\n        </form>\n        <span class=\"newsletter-sub\">No spam. One actionable insight every Tuesday.</span>\n      </div>\n    </div>\n\n    <!-- Bottom Bar -->\n    <div class=\"container footer-bottom\">\n      <div class=\"footer-bottom-brand\">\n        <span class=\"footer-logo\">C</span>\n        <span>\u00a9 2026 ContextOS, Inc. All rights reserved.</span>\n      </div>\n      <div class=\"footer-legal\">\n        <a href=\"#privacy\">Privacy Policy</a>\n        <a href=\"#terms\">Terms of Service</a>\n        <a href=\"#security\">Security</a>\n      </div>\n    </div>\n  </footer>\n\n  <!-- ==================== SIGN UP / AUDIT MODAL ==================== -->\n  <div class=\"modal-backdrop\" id=\"signUpModal\">\n    <div class=\"modal-card\">\n      <div class=\"modal-header\">\n        <h3 class=\"modal-title\">Get Started with ContextOS</h3>\n        <button class=\"modal-close\" id=\"closeSignUpModal\">\u2715</button>\n      </div>\n      <div class=\"modal-body\">\n        <p class=\"modal-desc\">\n          Set up your team's autonomous institutional memory in under 48 hours. Zero manual documentation required.\n        </p>\n        <form id=\"leadCaptureForm\">\n          <div class=\"form-group\">\n            <label for=\"leadName\">Your Name</label>\n            <input type=\"text\" id=\"leadName\" class=\"form-input\" placeholder=\"e.g. Sarah Connor\" required>\n          </div>\n          <div class=\"form-group\">\n            <label for=\"leadEmail\">Work Email</label>\n            <input type=\"email\" id=\"leadEmail\" class=\"form-input\" placeholder=\"name@company.com\" required>\n          </div>\n          <div class=\"form-group\">\n            <label for=\"leadCompany\">Company Name & Headcount</label>\n            <input type=\"text\" id=\"leadCompany\" class=\"form-input\" placeholder=\"e.g. Acme Corp (45 employees)\" required>\n          </div>\n          <div class=\"form-group\">\n            <label for=\"leadTools\">Primary Work Tools</label>\n            <select id=\"leadTools\" class=\"form-input\">\n              <option value=\"slack-google\">Slack + Google Workspace</option>\n              <option value=\"slack-github\">Slack + GitHub + Notion</option>\n              <option value=\"teams-microsoft\">Microsoft Teams + Office 365</option>\n              <option value=\"other\">Other / Mixed</option>\n            </select>\n          </div>\n          <button type=\"submit\" class=\"btn btn-primary btn-block btn-lg\">Request 48-Hour Free Audit</button>\n        </form>\n      </div>\n    </div>\n  </div>\n\n  <!-- Toast Notification -->\n  <div class=\"toast\" id=\"siteToast\">Notification message</div>\n\n  \n";
const CSS_CONTENT = "/* ==========================================================================\n   ContextOS \u2022 Enterprise Design System\n   Aesthetic: Premium, Calm, Executive (Strictly NO RGB / Neon Glows)\n   ========================================================================== */\n\n:root {\n  /* Neutral Color Palette (No RGB / Neon) */\n  --color-bg-base: #f8fafc;\n  --color-bg-surface: #ffffff;\n  --color-bg-subtle: #f1f5f9;\n  --color-bg-muted: #e2e8f0;\n\n  --color-text-main: #0f172a;\n  --color-text-body: #334155;\n  --color-text-muted: #64748b;\n  --color-text-subtle: #94a3b8;\n\n  --color-border: #e2e8f0;\n  --color-border-hover: #cbd5e1;\n\n  /* Executive Accent (Restrained Deep Ink & Navy) */\n  --color-primary: #0f172a;\n  --color-primary-hover: #1e293b;\n  --color-brand-blue: #1d4ed8;\n  --color-brand-blue-hover: #1e40af;\n  --color-danger-subtle: #fee2e2;\n  --color-danger-text: #991b1b;\n  --color-success-subtle: #dcfce7;\n  --color-success-text: #166534;\n\n  /* Typography */\n  --font-sans: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\n  --font-mono: 'JetBrains Mono', monospace;\n\n  /* Spacing & Borders */\n  --radius-sm: 6px;\n  --radius-md: 10px;\n  --radius-lg: 16px;\n  --radius-xl: 20px;\n\n  /* Shadows (Natural, Soft, Matte - No Glowing Radials) */\n  --shadow-sm: 0 1px 2px 0 rgba(15, 23, 42, 0.05);\n  --shadow-md: 0 4px 6px -1px rgba(15, 23, 42, 0.08), 0 2px 4px -2px rgba(15, 23, 42, 0.04);\n  --shadow-lg: 0 10px 15px -3px rgba(15, 23, 42, 0.08), 0 4px 6px -4px rgba(15, 23, 42, 0.04);\n  --shadow-window: 0 20px 25px -5px rgba(15, 23, 42, 0.1), 0 8px 10px -6px rgba(15, 23, 42, 0.04);\n\n  --transition: all 0.2s ease-in-out;\n}\n\n* {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nhtml {\n  scroll-behavior: smooth;\n}\n\nbody {\n  background-color: var(--color-bg-base);\n  color: var(--color-text-body);\n  font-family: var(--font-sans);\n  line-height: 1.6;\n  -webkit-font-smoothing: antialiased;\n}\n\n.container {\n  max-width: 1200px;\n  margin: 0 auto;\n  padding: 0 24px;\n}\n\n/* ==========================================================================\n   Buttons & Core Components\n   ========================================================================== */\n.btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  font-family: inherit;\n  font-weight: 600;\n  font-size: 0.9rem;\n  border-radius: var(--radius-sm);\n  padding: 9px 18px;\n  cursor: pointer;\n  border: 1px solid transparent;\n  transition: var(--transition);\n  text-decoration: none;\n}\n\n.btn-primary {\n  background-color: var(--color-primary);\n  color: #ffffff;\n}\n\n.btn-primary:hover {\n  background-color: var(--color-primary-hover);\n}\n\n.btn-secondary-subtle {\n  background-color: transparent;\n  color: var(--color-text-main);\n  border-color: var(--color-border);\n}\n\n.btn-secondary-subtle:hover {\n  background-color: var(--color-bg-subtle);\n  border-color: var(--color-border-hover);\n}\n\n.btn-outline {\n  background-color: var(--color-bg-surface);\n  color: var(--color-text-main);\n  border-color: var(--color-border);\n  box-shadow: var(--shadow-sm);\n}\n\n.btn-outline:hover {\n  background-color: var(--color-bg-subtle);\n  border-color: var(--color-border-hover);\n}\n\n.btn-lg {\n  padding: 12px 24px;\n  font-size: 0.95rem;\n  border-radius: var(--radius-md);\n}\n\n.btn-block {\n  width: 100%;\n}\n\n/* ==========================================================================\n   1. HEADER\n   ========================================================================== */\n.site-header {\n  position: sticky;\n  top: 0;\n  z-index: 100;\n  background-color: rgba(255, 255, 255, 0.92);\n  backdrop-filter: blur(12px);\n  border-bottom: 1px solid var(--color-border);\n}\n\n.header-inner {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  height: 70px;\n}\n\n.brand-logo {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  text-decoration: none;\n  color: var(--color-text-main);\n}\n\n.logo-mark {\n  width: 32px;\n  height: 32px;\n  border-radius: var(--radius-sm);\n  background-color: var(--color-primary);\n  color: #ffffff;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-weight: 800;\n  font-size: 1rem;\n}\n\n.brand-name {\n  font-size: 1.15rem;\n  font-weight: 600;\n  letter-spacing: -0.02em;\n}\n\n.brand-name strong {\n  font-weight: 800;\n}\n\n.nav-menu {\n  display: flex;\n  align-items: center;\n  gap: 28px;\n}\n\n.nav-link {\n  text-decoration: none;\n  color: var(--color-text-muted);\n  font-size: 0.9rem;\n  font-weight: 500;\n  transition: var(--transition);\n}\n\n.nav-link:hover, .nav-link.active {\n  color: var(--color-text-main);\n}\n\n.header-actions {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n/* ==========================================================================\n   2. HERO SECTION\n   ========================================================================== */\n.hero-section {\n  padding: 80px 0 70px 0;\n  background-color: var(--color-bg-base);\n  border-bottom: 1px solid var(--color-border);\n}\n\n.hero-inner {\n  display: grid;\n  grid-template-columns: 1.1fr 1fr;\n  gap: 56px;\n  align-items: center;\n}\n\n.hero-pill {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  background-color: var(--color-bg-surface);\n  border: 1px solid var(--color-border);\n  border-radius: 999px;\n  padding: 5px 14px;\n  font-size: 0.78rem;\n  font-weight: 600;\n  color: var(--color-text-main);\n  margin-bottom: 24px;\n  box-shadow: var(--shadow-sm);\n}\n\n.pill-dot {\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  background-color: var(--color-brand-blue);\n}\n\n.hero-headline {\n  font-size: 3rem;\n  font-weight: 800;\n  line-height: 1.15;\n  letter-spacing: -0.035em;\n  color: var(--color-text-main);\n  margin-bottom: 20px;\n}\n\n.hero-subtext {\n  font-size: 1.1rem;\n  color: var(--color-text-body);\n  line-height: 1.65;\n  margin-bottom: 32px;\n}\n\n.hero-cta-group {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n  margin-bottom: 36px;\n}\n\n.hero-proof-bar {\n  display: flex;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 20px;\n  font-size: 0.82rem;\n  color: var(--color-text-muted);\n}\n\n.proof-item {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.proof-check {\n  color: var(--color-success-text);\n  font-weight: bold;\n}\n\n/* Hero Right Window Mockup */\n.mockup-window {\n  background-color: var(--color-bg-surface);\n  border: 1px solid var(--color-border);\n  border-radius: var(--radius-lg);\n  box-shadow: var(--shadow-window);\n  overflow: hidden;\n}\n\n.mockup-chrome {\n  background-color: var(--color-bg-subtle);\n  border-bottom: 1px solid var(--color-border);\n  padding: 12px 18px;\n  display: flex;\n  align-items: center;\n  gap: 14px;\n}\n\n.chrome-dots {\n  display: flex;\n  gap: 6px;\n}\n\n.chrome-dots .dot {\n  width: 10px;\n  height: 10px;\n  border-radius: 50%;\n}\n\n.dot.red { background-color: #f87171; }\n.dot.yellow { background-color: #fbbf24; }\n.dot.green { background-color: #34d399; }\n\n.chrome-url {\n  font-family: var(--font-mono);\n  font-size: 0.72rem;\n  color: var(--color-text-muted);\n  background-color: var(--color-bg-surface);\n  border: 1px solid var(--color-border);\n  padding: 4px 12px;\n  border-radius: var(--radius-sm);\n  flex: 1;\n}\n\n.chrome-badge {\n  font-size: 0.7rem;\n  font-weight: 600;\n  color: var(--color-brand-blue);\n  background-color: #eff6ff;\n  border: 1px solid #bfdbfe;\n  padding: 2px 8px;\n  border-radius: 999px;\n}\n\n.mockup-body {\n  padding: 22px;\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n}\n\n.mockup-search {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  background-color: var(--color-bg-subtle);\n  border: 1px solid var(--color-border);\n  border-radius: var(--radius-md);\n  padding: 10px 14px;\n}\n\n.mockup-search input {\n  flex: 1;\n  background: transparent;\n  border: none;\n  outline: none;\n  color: var(--color-text-main);\n  font-family: inherit;\n  font-size: 0.88rem;\n  font-weight: 500;\n}\n\n.mockup-tag {\n  font-size: 0.72rem;\n  font-weight: 700;\n  background-color: #fef3c7;\n  color: #92400e;\n  padding: 2px 8px;\n  border-radius: var(--radius-sm);\n}\n\n.mockup-card {\n  background-color: #ffffff;\n  border: 1px solid var(--color-border);\n  border-radius: var(--radius-md);\n  padding: 18px;\n}\n\n.mockup-card.alert-card {\n  border-left: 4px solid #f59e0b;\n}\n\n.card-status-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-bottom: 10px;\n}\n\n.flag-pill {\n  font-size: 0.72rem;\n  font-weight: 700;\n  text-transform: uppercase;\n  color: #b45309;\n}\n\n.flag-date {\n  font-size: 0.72rem;\n  color: var(--color-text-muted);\n  font-family: var(--font-mono);\n}\n\n.card-headline {\n  font-size: 1rem;\n  font-weight: 700;\n  color: var(--color-text-main);\n  margin-bottom: 6px;\n}\n\n.card-desc {\n  font-size: 0.84rem;\n  color: var(--color-text-body);\n  line-height: 1.5;\n  margin-bottom: 12px;\n}\n\n.card-meta-row {\n  display: flex;\n  gap: 10px;\n  margin-bottom: 12px;\n}\n\n.meta-tag {\n  font-size: 0.75rem;\n  padding: 3px 8px;\n  background-color: var(--color-success-subtle);\n  color: var(--color-success-text);\n  border-radius: var(--radius-sm);\n}\n\n.meta-tag.danger {\n  background-color: var(--color-danger-subtle);\n  color: var(--color-danger-text);\n}\n\n.card-outcome-banner {\n  background-color: var(--color-bg-subtle);\n  border-radius: var(--radius-sm);\n  padding: 8px 12px;\n  font-size: 0.78rem;\n  color: var(--color-text-main);\n}\n\n.mockup-stream-preview {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  font-size: 0.72rem;\n  color: var(--color-text-muted);\n}\n\n.stream-pill {\n  background-color: var(--color-bg-subtle);\n  border: 1px solid var(--color-border);\n  padding: 3px 8px;\n  border-radius: var(--radius-sm);\n  color: var(--color-text-body);\n}\n\n/* ==========================================================================\n   3. FEATURES SECTION (CARD 1, 2, 3)\n   ========================================================================== */\n.features-section {\n  padding: 96px 0;\n  background-color: var(--color-bg-surface);\n  border-bottom: 1px solid var(--color-border);\n}\n\n.section-header {\n  text-align: center;\n  max-width: 720px;\n  margin: 0 auto 60px auto;\n}\n\n.section-tag {\n  font-size: 0.8rem;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n  color: var(--color-text-muted);\n  display: block;\n  margin-bottom: 12px;\n}\n\n.section-title {\n  font-size: 2.25rem;\n  font-weight: 800;\n  color: var(--color-text-main);\n  letter-spacing: -0.03em;\n  line-height: 1.25;\n  margin-bottom: 16px;\n}\n\n.section-subtitle {\n  font-size: 1.05rem;\n  color: var(--color-text-body);\n}\n\n.features-grid {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 28px;\n}\n\n.feature-card {\n  background-color: var(--color-bg-base);\n  border: 1px solid var(--color-border);\n  border-radius: var(--radius-lg);\n  padding: 32px 28px;\n  display: flex;\n  flex-direction: column;\n  position: relative;\n  transition: var(--transition);\n}\n\n.feature-card:hover {\n  border-color: var(--color-border-hover);\n  box-shadow: var(--shadow-md);\n  transform: translateY(-2px);\n}\n\n.feature-card.highlight-card {\n  background-color: #ffffff;\n  border-color: #cbd5e1;\n  box-shadow: var(--shadow-sm);\n}\n\n.card-icon-wrap {\n  width: 44px;\n  height: 44px;\n  border-radius: var(--radius-md);\n  background-color: var(--color-bg-surface);\n  border: 1px solid var(--color-border);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  color: var(--color-text-main);\n  margin-bottom: 20px;\n}\n\n.card-number {\n  position: absolute;\n  top: 28px;\n  right: 28px;\n  font-family: var(--font-mono);\n  font-size: 0.82rem;\n  font-weight: 600;\n  color: var(--color-text-subtle);\n}\n\n.card-title {\n  font-size: 1.25rem;\n  font-weight: 700;\n  color: var(--color-text-main);\n  margin-bottom: 12px;\n}\n\n.card-body {\n  font-size: 0.92rem;\n  color: var(--color-text-body);\n  line-height: 1.6;\n  margin-bottom: 24px;\n}\n\n.card-list {\n  list-style: none;\n  margin-top: auto;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  font-size: 0.85rem;\n  color: var(--color-text-main);\n  border-top: 1px solid var(--color-border);\n  padding-top: 20px;\n}\n\n.card-list li::before {\n  content: \"\u2022\";\n  color: var(--color-text-muted);\n  margin-right: 8px;\n}\n\n/* ==========================================================================\n   4. TESTIMONIALS & SOCIAL PROOF\n   ========================================================================== */\n.social-proof-section {\n  padding: 88px 0;\n  background-color: var(--color-bg-base);\n  border-bottom: 1px solid var(--color-border);\n}\n\n.metrics-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  background-color: var(--color-bg-surface);\n  border: 1px solid var(--color-border);\n  border-radius: var(--radius-lg);\n  padding: 32px 40px;\n  margin-bottom: 60px;\n  box-shadow: var(--shadow-sm);\n}\n\n.metric-block {\n  text-align: center;\n  flex: 1;\n}\n\n.metric-value {\n  display: block;\n  font-size: 2.2rem;\n  font-weight: 800;\n  font-family: var(--font-mono);\n  color: var(--color-text-main);\n  letter-spacing: -0.02em;\n  margin-bottom: 4px;\n}\n\n.metric-desc {\n  font-size: 0.85rem;\n  color: var(--color-text-muted);\n}\n\n.metric-divider {\n  width: 1px;\n  height: 48px;\n  background-color: var(--color-border);\n}\n\n.testimonials-grid {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 28px;\n}\n\n.testimonial-card {\n  background-color: var(--color-bg-surface);\n  border: 1px solid var(--color-border);\n  border-radius: var(--radius-lg);\n  padding: 28px;\n  display: flex;\n  flex-direction: column;\n  justify-content: space-between;\n  box-shadow: var(--shadow-sm);\n}\n\n.testimonial-quote {\n  font-size: 0.95rem;\n  color: var(--color-text-main);\n  line-height: 1.65;\n  margin-bottom: 24px;\n  font-style: normal;\n}\n\n.testimonial-author {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n.author-avatar {\n  width: 36px;\n  height: 36px;\n  border-radius: 50%;\n  background-color: var(--color-primary);\n  color: #ffffff;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-weight: 700;\n  font-size: 0.8rem;\n}\n\n.author-info {\n  display: flex;\n  flex-direction: column;\n}\n\n.author-name {\n  font-size: 0.88rem;\n  font-weight: 700;\n  color: var(--color-text-main);\n}\n\n.author-role {\n  font-size: 0.75rem;\n  color: var(--color-text-muted);\n}\n\n/* ==========================================================================\n   5. PRICING & FAQ\n   ========================================================================== */\n.pricing-faq-section {\n  padding: 96px 0;\n  background-color: var(--color-bg-surface);\n  border-bottom: 1px solid var(--color-border);\n}\n\n.billing-toggle {\n  display: inline-flex;\n  align-items: center;\n  gap: 12px;\n  background-color: var(--color-bg-subtle);\n  border: 1px solid var(--color-border);\n  border-radius: 999px;\n  padding: 6px 16px;\n  margin-top: 24px;\n}\n\n.toggle-label {\n  font-size: 0.85rem;\n  font-weight: 600;\n  color: var(--color-text-muted);\n  cursor: pointer;\n}\n\n.toggle-label.active {\n  color: var(--color-text-main);\n}\n\n.discount-badge {\n  background-color: var(--color-success-subtle);\n  color: var(--color-success-text);\n  font-size: 0.72rem;\n  padding: 2px 8px;\n  border-radius: 999px;\n  margin-left: 4px;\n}\n\n.toggle-switch {\n  width: 44px;\n  height: 24px;\n  background-color: var(--color-primary);\n  border-radius: 999px;\n  border: none;\n  cursor: pointer;\n  position: relative;\n  transition: var(--transition);\n}\n\n.toggle-switch::after {\n  content: \"\";\n  position: absolute;\n  top: 3px;\n  right: 3px;\n  width: 18px;\n  height: 18px;\n  background-color: #ffffff;\n  border-radius: 50%;\n  transition: var(--transition);\n}\n\n.toggle-switch.monthly::after {\n  right: 23px;\n}\n\n.pricing-grid {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 28px;\n  margin-bottom: 80px;\n  align-items: stretch;\n}\n\n.pricing-card {\n  background-color: var(--color-bg-base);\n  border: 1px solid var(--color-border);\n  border-radius: var(--radius-lg);\n  padding: 36px 30px;\n  display: flex;\n  flex-direction: column;\n  position: relative;\n}\n\n.pricing-card.featured {\n  background-color: #ffffff;\n  border: 2px solid var(--color-primary);\n  box-shadow: var(--shadow-lg);\n  transform: scale(1.02);\n}\n\n.popular-ribbon {\n  position: absolute;\n  top: -13px;\n  left: 50%;\n  transform: translateX(-50%);\n  background-color: var(--color-primary);\n  color: #ffffff;\n  font-size: 0.72rem;\n  font-weight: 700;\n  letter-spacing: 0.05em;\n  padding: 3px 12px;\n  border-radius: 999px;\n}\n\n.plan-name {\n  font-size: 1.35rem;\n  font-weight: 800;\n  color: var(--color-text-main);\n  margin-bottom: 6px;\n}\n\n.plan-desc {\n  font-size: 0.88rem;\n  color: var(--color-text-muted);\n  min-height: 42px;\n}\n\n.plan-price {\n  margin: 28px 0;\n  display: flex;\n  align-items: baseline;\n  gap: 4px;\n}\n\n.plan-price .currency {\n  font-size: 1.4rem;\n  font-weight: 700;\n  color: var(--color-text-main);\n}\n\n.plan-price .price-val {\n  font-size: 3rem;\n  font-weight: 800;\n  font-family: var(--font-mono);\n  color: var(--color-text-main);\n  line-height: 1;\n}\n\n.plan-price .price-val.custom {\n  font-size: 2.2rem;\n  font-family: var(--font-sans);\n}\n\n.plan-price .period {\n  font-size: 0.85rem;\n  color: var(--color-text-muted);\n}\n\n.plan-features {\n  list-style: none;\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  font-size: 0.88rem;\n  color: var(--color-text-main);\n  margin-bottom: 32px;\n  flex: 1;\n}\n\n.plan-features li::before {\n  content: \"\u2713\";\n  color: var(--color-brand-blue);\n  font-weight: bold;\n  margin-right: 10px;\n}\n\n/* FAQ Accordion */\n.faq-container {\n  max-width: 800px;\n  margin: 0 auto;\n}\n\n.faq-title {\n  text-align: center;\n  font-size: 1.75rem;\n  font-weight: 800;\n  color: var(--color-text-main);\n  margin-bottom: 36px;\n}\n\n.faq-accordion {\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n}\n\n.faq-item {\n  border: 1px solid var(--color-border);\n  border-radius: var(--radius-md);\n  background-color: var(--color-bg-base);\n  overflow: hidden;\n  transition: var(--transition);\n}\n\n.faq-question {\n  width: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 18px 24px;\n  background: transparent;\n  border: none;\n  font-family: inherit;\n  font-size: 0.95rem;\n  font-weight: 700;\n  color: var(--color-text-main);\n  text-align: left;\n  cursor: pointer;\n}\n\n.faq-icon {\n  font-size: 1.25rem;\n  font-weight: 400;\n  color: var(--color-text-muted);\n  transition: var(--transition);\n}\n\n.faq-answer {\n  max-height: 0;\n  overflow: hidden;\n  transition: max-height 0.25s ease-out;\n  padding: 0 24px;\n}\n\n.faq-answer p {\n  padding-bottom: 18px;\n  font-size: 0.9rem;\n  color: var(--color-text-body);\n  line-height: 1.6;\n}\n\n.faq-item.active .faq-answer {\n  max-height: 300px;\n}\n\n.faq-item.active .faq-icon {\n  transform: rotate(45deg);\n}\n\n/* ==========================================================================\n   6. FOOTER\n   ========================================================================== */\n.site-footer {\n  background-color: var(--color-bg-base);\n  padding: 80px 0 40px 0;\n  border-top: 1px solid var(--color-border);\n}\n\n.footer-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr 1fr 1.6fr;\n  gap: 48px;\n  margin-bottom: 64px;\n}\n\n.footer-col-title {\n  font-size: 0.82rem;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n  color: var(--color-text-main);\n  margin-bottom: 18px;\n}\n\n.footer-links {\n  list-style: none;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.footer-links a {\n  text-decoration: none;\n  font-size: 0.88rem;\n  color: var(--color-text-muted);\n  transition: var(--transition);\n}\n\n.footer-links a:hover {\n  color: var(--color-text-main);\n}\n\n.newsletter-desc {\n  font-size: 0.88rem;\n  color: var(--color-text-muted);\n  line-height: 1.5;\n  margin-bottom: 16px;\n}\n\n.newsletter-form {\n  display: flex;\n  gap: 8px;\n  margin-bottom: 8px;\n}\n\n.newsletter-input {\n  flex: 1;\n  background-color: var(--color-bg-surface);\n  border: 1px solid var(--color-border);\n  border-radius: var(--radius-sm);\n  padding: 9px 14px;\n  font-size: 0.88rem;\n  color: var(--color-text-main);\n  outline: none;\n}\n\n.newsletter-input:focus {\n  border-color: var(--color-primary);\n}\n\n.btn-newsletter {\n  white-space: nowrap;\n}\n\n.newsletter-sub {\n  font-size: 0.75rem;\n  color: var(--color-text-subtle);\n  display: block;\n}\n\n.footer-bottom {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  border-top: 1px solid var(--color-border);\n  padding-top: 32px;\n  font-size: 0.82rem;\n  color: var(--color-text-muted);\n}\n\n.footer-bottom-brand {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n\n.footer-logo {\n  width: 22px;\n  height: 22px;\n  border-radius: 4px;\n  background-color: var(--color-primary);\n  color: #fff;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  font-weight: 700;\n  font-size: 0.72rem;\n}\n\n.footer-legal {\n  display: flex;\n  gap: 20px;\n}\n\n.footer-legal a {\n  color: var(--color-text-muted);\n  text-decoration: none;\n}\n\n.footer-legal a:hover {\n  color: var(--color-text-main);\n}\n\n/* ==========================================================================\n   MODAL & TOAST\n   ========================================================================== */\n.modal-backdrop {\n  position: fixed;\n  inset: 0;\n  background-color: rgba(15, 23, 42, 0.6);\n  backdrop-filter: blur(4px);\n  z-index: 200;\n  display: none;\n  align-items: center;\n  justify-content: center;\n  padding: 20px;\n}\n\n.modal-backdrop.open {\n  display: flex;\n}\n\n.modal-card {\n  background-color: #ffffff;\n  border: 1px solid var(--color-border);\n  border-radius: var(--radius-lg);\n  width: 100%;\n  max-width: 520px;\n  box-shadow: var(--shadow-lg);\n  overflow: hidden;\n}\n\n.modal-header {\n  padding: 20px 24px;\n  border-bottom: 1px solid var(--color-border);\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n\n.modal-title {\n  font-size: 1.15rem;\n  font-weight: 700;\n  color: var(--color-text-main);\n}\n\n.modal-close {\n  background: transparent;\n  border: none;\n  font-size: 1.2rem;\n  cursor: pointer;\n  color: var(--color-text-muted);\n}\n\n.modal-body {\n  padding: 24px;\n}\n\n.modal-desc {\n  font-size: 0.88rem;\n  color: var(--color-text-body);\n  margin-bottom: 20px;\n}\n\n.form-group {\n  margin-bottom: 16px;\n}\n\n.form-group label {\n  display: block;\n  font-size: 0.82rem;\n  font-weight: 600;\n  color: var(--color-text-main);\n  margin-bottom: 6px;\n}\n\n.form-input {\n  width: 100%;\n  background-color: var(--color-bg-base);\n  border: 1px solid var(--color-border);\n  border-radius: var(--radius-sm);\n  padding: 10px 14px;\n  font-size: 0.88rem;\n  color: var(--color-text-main);\n  font-family: inherit;\n  outline: none;\n}\n\n.form-input:focus {\n  border-color: var(--color-primary);\n}\n\n.toast {\n  position: fixed;\n  bottom: 24px;\n  right: 24px;\n  background-color: var(--color-primary);\n  color: #ffffff;\n  padding: 12px 20px;\n  border-radius: var(--radius-sm);\n  font-size: 0.85rem;\n  font-weight: 600;\n  box-shadow: var(--shadow-md);\n  z-index: 300;\n  display: none;\n}\n\n/* ==========================================================================\n   RESPONSIVENESS\n   ========================================================================== */\n@media (max-width: 1024px) {\n  .hero-inner {\n    grid-template-columns: 1fr;\n    gap: 40px;\n  }\n  .features-grid, .pricing-grid, .testimonials-grid {\n    grid-template-columns: 1fr;\n  }\n  .pricing-card.featured {\n    transform: none;\n  }\n  .footer-grid {\n    grid-template-columns: 1fr 1fr;\n    gap: 36px;\n  }\n}\n\n@media (max-width: 768px) {\n  .nav-menu {\n    display: none;\n  }\n  .hero-headline {\n    font-size: 2.2rem;\n  }\n  .metrics-row {\n    flex-direction: column;\n    gap: 24px;\n  }\n  .metric-divider {\n    display: none;\n  }\n  .footer-grid {\n    grid-template-columns: 1fr;\n  }\n  .footer-bottom {\n    flex-direction: column;\n    gap: 16px;\n    text-align: center;\n  }\n}\n";
const SCRIPT_CODE = "// ContextOS \u2022 Website Interactions & Behavior\ndocument.addEventListener('DOMContentLoaded', () => {\n\n  // --- 1. TOAST NOTIFICATION UTILITY ---\n  const toast = document.getElementById('siteToast');\n  function showToast(message) {\n    if (!toast) return;\n    toast.textContent = message;\n    toast.style.display = 'block';\n    setTimeout(() => {\n      toast.style.display = 'none';\n    }, 3500);\n  }\n\n  // --- 2. MODAL CONTROLS (SIGN UP & AUDIT CAPTURE) ---\n  const signUpModal = document.getElementById('signUpModal');\n  const closeSignUpModal = document.getElementById('closeSignUpModal');\n  const navSignUpBtn = document.getElementById('navSignUpBtn');\n  const navSignInBtn = document.getElementById('navSignInBtn');\n  const heroGetStartedBtn = document.getElementById('heroGetStartedBtn');\n  const planButtons = document.querySelectorAll('.btn-plan');\n\n  function openModal(defaultPlan = \"\") {\n    if (!signUpModal) return;\n    signUpModal.classList.add('open');\n    const companyInput = document.getElementById('leadCompany');\n    if (companyInput && defaultPlan) {\n      companyInput.placeholder = `e.g. Acme Corp (Selected: ${defaultPlan})`;\n    }\n  }\n\n  function closeModal() {\n    if (!signUpModal) return;\n    signUpModal.classList.remove('open');\n  }\n\n  navSignUpBtn?.addEventListener('click', () => openModal(\"Growth Plan\"));\n  navSignInBtn?.addEventListener('click', () => {\n    showToast(\"Redirecting to Single Sign-On (SSO / Google Workspace)...\");\n  });\n  heroGetStartedBtn?.addEventListener('click', () => openModal(\"14-Day Free Audit\"));\n  closeSignUpModal?.addEventListener('click', closeModal);\n\n  planButtons.forEach(btn => {\n    btn.addEventListener('click', () => {\n      const plan = btn.dataset.plan || \"Selected Plan\";\n      openModal(plan);\n    });\n  });\n\n  // Close modal when clicking on backdrop\n  signUpModal?.addEventListener('click', (e) => {\n    if (e.target === signUpModal) closeModal();\n  });\n\n  // Handle Lead Capture Form Submission\n  const leadForm = document.getElementById('leadCaptureForm');\n  leadForm?.addEventListener('submit', (e) => {\n    e.preventDefault();\n    const name = document.getElementById('leadName')?.value || \"Founder\";\n    const email = document.getElementById('leadEmail')?.value || \"\";\n    const company = document.getElementById('leadCompany')?.value || \"\";\n\n    closeModal();\n    showToast(`\u2713 Audit requested for ${company}! We'll email ${email} within 2 hours.`);\n    leadForm.reset();\n  });\n\n  // --- 3. FAQ ACCORDION ---\n  const faqItems = document.querySelectorAll('.faq-item');\n  faqItems.forEach(item => {\n    const questionBtn = item.querySelector('.faq-question');\n    questionBtn?.addEventListener('click', () => {\n      const isOpen = item.classList.contains('active');\n      // Close all other items\n      faqItems.forEach(i => i.classList.remove('active'));\n      // Toggle current item\n      if (!isOpen) {\n        item.classList.add('active');\n      }\n    });\n  });\n\n  // Open first FAQ by default\n  if (faqItems.length > 0) {\n    faqItems[0].classList.add('active');\n  }\n\n  // --- 4. PRICING BILLING TOGGLE (MONTHLY VS ANNUAL) ---\n  const billingToggleBtn = document.getElementById('billingToggleBtn');\n  const monthlyLabel = document.getElementById('monthlyLabel');\n  const annualLabel = document.getElementById('annualLabel');\n  const priceValues = document.querySelectorAll('.price-val[data-monthly]');\n\n  let isAnnual = true; // Default annual\n\n  function updatePricing() {\n    if (isAnnual) {\n      billingToggleBtn?.classList.remove('monthly');\n      annualLabel?.classList.add('active');\n      monthlyLabel?.classList.remove('active');\n      priceValues.forEach(el => {\n        el.textContent = el.dataset.annual;\n      });\n    } else {\n      billingToggleBtn?.classList.add('monthly');\n      annualLabel?.classList.remove('active');\n      monthlyLabel?.classList.add('active');\n      priceValues.forEach(el => {\n        el.textContent = el.dataset.monthly;\n      });\n    }\n  }\n\n  billingToggleBtn?.addEventListener('click', () => {\n    isAnnual = !isAnnual;\n    updatePricing();\n  });\n\n  monthlyLabel?.addEventListener('click', () => {\n    isAnnual = false;\n    updatePricing();\n  });\n\n  annualLabel?.addEventListener('click', () => {\n    isAnnual = true;\n    updatePricing();\n  });\n\n  // --- 5. INTERACTIVE HERO PREVIEW (CYCLE QUERIES) ---\n  const demoQueryInput = document.getElementById('demoQueryInput');\n  const sampleQueries = [\n    {\n      query: \"Should we switch checkout provider to Adyen?\",\n      headline: \"Adyen Evaluated & Rejected for European Rollout\",\n      desc: \"Sarah Jenkins (Billing Lead) tested Adyen against Stripe Connect. Minimum \u20ac120/mo platform charge & KYC verification latency in Germany led to an 18% onboarding abandonment rate.\",\n      decision: \"Retain Stripe Connect\",\n      rejected: \"Adyen\",\n      intercept: \"Prevented 3 weeks of duplicated vendor evaluations.\"\n    },\n    {\n      query: \"Can we rewrite search infrastructure using Elasticsearch?\",\n      headline: \"Elasticsearch Migration Evaluated & Aborted\",\n      desc: \"David Chen proved a dedicated Elasticsearch cluster incurs $2,400/mo infrastructure bloat and requires full-time DevOps maintenance. Retained Postgres pg_trgm + Meilisearch.\",\n      decision: \"Postgres pg_trgm + Meilisearch\",\n      rejected: \"Elasticsearch / OpenSearch\",\n      intercept: \"Saved $28,800/yr in unmanaged cloud compute costs.\"\n    },\n    {\n      query: \"Why did we cancel the offshore mobile QA agency contract?\",\n      headline: \"Outsourced QA Agency Engagement Terminated\",\n      desc: \"Elena Rostova (VP Product) terminated the third-party agreement due to 36-hour timezone latency and missed WebSocket regressions. Replaced with Playwright CI automation.\",\n      decision: \"Automated Playwright Suite\",\n      rejected: \"Offshore Manual QA Contractor\",\n      intercept: \"Replaced 36-hr feedback lag with 3-minute automated PR checks.\"\n    }\n  ];\n\n  let queryIndex = 0;\n  if (demoQueryInput) {\n    demoQueryInput.style.cursor = 'pointer';\n    demoQueryInput.title = 'Click to test other historical company decisions';\n    \n    demoQueryInput.addEventListener('click', () => {\n      queryIndex = (queryIndex + 1) % sampleQueries.length;\n      const data = sampleQueries[queryIndex];\n\n      demoQueryInput.value = data.query;\n      const cardHeadline = document.querySelector('.card-headline');\n      const cardDesc = document.querySelector('.card-desc');\n      const metaTags = document.querySelectorAll('.meta-tag');\n      const outcomeBanner = document.querySelector('.card-outcome-banner');\n\n      if (cardHeadline) cardHeadline.textContent = data.headline;\n      if (cardDesc) cardDesc.textContent = data.desc;\n      if (metaTags[0]) metaTags[0].innerHTML = `<strong>Decision:</strong> ${data.decision}`;\n      if (metaTags[1]) metaTags[1].innerHTML = `<strong>Rejected:</strong> ${data.rejected}`;\n      if (outcomeBanner) outcomeBanner.innerHTML = `<strong>ContextOS Intercept:</strong> ${data.intercept}`;\n\n      showToast(\"\u26a1 Intercepting live context from simulated workspace...\");\n    });\n  }\n\n  // --- 6. NEWSLETTER SUBSCRIPTION ---\n  const newsletterForm = document.getElementById('newsletterForm');\n  newsletterForm?.addEventListener('submit', (e) => {\n    e.preventDefault();\n    const email = document.getElementById('newsletterEmail')?.value;\n    showToast(`Thank you! Subscribed ${email} to our weekly scaling dispatch.`);\n    newsletterForm.reset();\n  });\n\n});\n";

export default function ContextOSPage() {
  const mountedRef = useRef(false);

  useEffect(() => {
    if (mountedRef.current) return;
    mountedRef.current = true;

    const styleEl = document.createElement('style');
    styleEl.id = 'contextos-home-styles';
    styleEl.innerHTML = CSS_CONTENT;
    document.head.appendChild(styleEl);

    try {
      const runLogic = new Function(SCRIPT_CODE);
      runLogic();
    } catch (e) {
      console.error('ContextOS script error:', e);
    }

    return () => {
      const el = document.getElementById('contextos-home-styles');
      if (el) el.remove();
    };
  }, []);

  return (
    <div
      dangerouslySetInnerHTML={{ __html: BODY_CONTENT }}
      suppressHydrationWarning
    />
  );
}
